{
  "states": [
    "Not Authenticated",
    "Authenticated",
    "Selected",
    "Logout"
  ],
  "transitions": [
    {
      "from": "Not Authenticated",
      "event": "successful LOGIN or AUTHENTICATE command",
      "action": "",
      "to": "Authenticated"
    },
    {
      "from": "Not Authenticated",
      "event": "LOGOUT command, server shutdown, or connection closed",
      "action": "server MUST send an untagged BYE response and a tagged OK response",
      "to": "Logout"
    },
    {
      "from": "Authenticated",
      "event": "successful SELECT or EXAMINE command",
      "action": "",
      "to": "Selected"
    },
    {
      "from": "Authenticated",
      "event": "LOGOUT command, server shutdown, or connection closed",
      "action": "server MUST send an untagged BYE response and a tagged OK response",
      "to": "Logout"
    },
    {
      "from": "Selected",
      "event": "CLOSE or UNSELECT command, unsolicited CLOSED response code, or failed SELECT or EXAMINE command",
      "action": "",
      "to": "Authenticated"
    },
    {
      "from": "Selected",
      "event": "LOGOUT command, server shutdown, or connection closed",
      "action": "server MUST send an untagged BYE response and a tagged OK response",
      "to": "Logout"
    }
  ]
}

{
  "states": [
    "not authenticated state",
    "authenticated state",
    "selected state"
  ],
  "transitions": [
    {
      "from": "not authenticated state",
      "event": "AUTHENTICATE or LOGIN",
      "action": "establishes authentication",
      "to": "authenticated state"
    },
    {
      "from": "not authenticated state",
      "event": "STARTTLS",
      "action": "remains in the non-authenticated state",
      "to": "not authenticated state"
    }
  ]
}

{
  "states": [
    "authenticated state",
    "selected state"
  ],
  "transitions": [
    {
      "from": "authenticated state",
      "event": "SELECT",
      "action": "OK - select completed, now in selected state",
      "to": "selected state"
    },
    {
      "from": "authenticated state",
      "event": "EXAMINE",
      "action": "OK - examine completed, now in selected state",
      "to": "selected state"
    }
  ]
}

{
  "states": [
    "Selected State",
    "authenticated state"
  ],
  "transitions": [
    {
      "from": "Selected State",
      "event": "CLOSE",
      "action": "OK - close completed",
      "to": "authenticated state"
    },
    {
      "from": "Selected State",
      "event": "UNSELECT",
      "action": "OK - unselect completed",
      "to": "authenticated state"
    }
  ]
}

{
  "states": [
    "Not Authenticated",
    "Authenticated",
    "Selected Mailbox",
    "Disconnected"
  ],
  "transitions": [
    {
      "from": "Not Authenticated",
      "event": "LOGIN or AUTHENTICATE",
      "action": "OK Response",
      "to": "Authenticated"
    },
    {
      "from": "Authenticated",
      "event": "SELECT or EXAMINE",
      "action": "OK Response",
      "to": "Selected Mailbox"
    },
    {
      "from": "Selected Mailbox",
      "event": "CLOSE or UNSELECT or SELECT",
      "action": "CLOSED Response Code or OK Response",
      "to": "Authenticated"
    },
    {
      "from": "Authenticated",
      "event": "LOGOUT or BYE",
      "action": "BYE Response",
      "to": "Disconnected"
    },
    {
      "from": "Selected Mailbox",
      "event": "LOGOUT or BYE",
      "action": "BYE Response",
      "to": "Disconnected"
    }
  ]
}
